-- This is all the Collection-log item Variables.

local function namedID(kind, name)
    local ok, value = pcall(function() return id[kind][name] end)
    if ok and type(value) == "number" and value % 1 == 0 and value ~= -1
        and (kind == "VarPlayer" or value > 0) then return value end
end

